/// <summary>
/// Copy to target contract class
/// </summary>
[DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(ISDAppIntgCopyDataToTargetUIBuilder)),
    SysOperationGroupAttribute("Criteria", "@SYS1046", '1')]
class ISDAppIntgCopyDataToTargetContract implements SysOperationValidatable
{
    str                         dmfExecutionJobQuery;
    str                         recRange;
    protected FormDataSource    callerFormDataSource;

    DMFOperation                dmfOperation;
    NoYesId                     dmfError;
    NoYesId                     dmfSelected;

}

