/// <summary>
/// Get or set dmf operation
/// </summary>
/// <param name = "_dmfOperation">DMF operation</param>
/// <returns>DMFOperation</returns>
[DataMemberAttribute, SysOperationGroupMemberAttribute("Criteria"), SysOperationDisplayOrderAttribute('1')]
public DMFOperation parmDMFOperation(DMFOperation   _dmfOperation = dmfOperation)
{
    dmfOperation = _dmfOperation;

    return dmfOperation;
}

/// <summary>
/// Get or set dmf error
/// </summary>
/// <param name = "_dmfError">DMF error</param>
/// <returns>NoYesId</returns>
[DataMemberAttribute, SysOperationGroupMemberAttribute("Criteria"), SysOperationDisplayOrderAttribute('2'), SysOperationLabel("@DMF216")]
public NoYesId parmDMFError(NoYesId   _dmfError = dmfError)
{
    dmfError = _dmfError;

    return dmfError;
}

/// <summary>
/// Get or set dmf selected records
/// </summary>
/// <param name = "_dmfSelected">DMF selected</param>
/// <returns>NoYesId</returns>
[DataMemberAttribute, SysOperationGroupMemberAttribute("Criteria"), SysOperationDisplayOrderAttribute('3'), SysOperationLabel("@DMF698")]
public NoYesId parmDMFSelected(NoYesId   _dmfSelected = dmfSelected)
{
    dmfSelected = _dmfSelected;

    return dmfSelected;
}

/// <summary>
/// Parm method for DMF definition group execution query
/// </summary>
/// <param name = "_dmfExecutionJobQuery">ISDAppIntgDMFDefinitionGroupExecution</param>
/// <returns>invent query</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false),
    AifQueryTypeAttribute('_dmfExecutionJobQuery', queryStr(ISDAppIntgDMFDefinitionGroupExecution))
]
public str parmStorePlanTableStatusPlannedQuery(str _dmfExecutionJobQuery = dmfExecutionJobQuery)
{
    dmfExecutionJobQuery = _dmfExecutionJobQuery;
    return dmfExecutionJobQuery;
}

/// <summary>
/// Parm method for DMF definition group execution id range
/// </summary>
/// <param name = "_recRange">Container</param>
/// <returns>DMF definition group execution id range</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public str parmDMFDefinitionGroupExecutionRange(str _recRange = recRange)
{
    recRange = _recRange;

    return recRange;
}

/// <summary>
/// Method to set query
/// </summary>
/// <param name = "_query">Query</param>
public void setQuery(Query _query)
{
    dmfExecutionJobQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// Method to get query
/// </summary>
/// <returns>Query</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(dmfExecutionJobQuery));
}

/// <summary>
/// Initiate Query
/// </summary>
public void initQuery()
{
    str                             range;
    FormDataSource                  dmfDefinitionGroupExecution_ds = this.parmFormDataSource();
    DMFDefinitionGroupExecution     markedRecords;
    MultiSelectionHelper            helper  = MultiSelectionHelper::construct();

    helper.parmDatasource(dmfDefinitionGroupExecution_ds);

    markedRecords = helper.getFirst();

    while (markedRecords)
    {
        range = queryRangeConcat(range, markedRecords.ExecutionId);
        markedRecords = helper.getNext();
    }

    if (range)
    {
        Query q = this.getQuery();
        QueryBuildDataSource qbds_dmfDefinitionGroupExecution  = q.dataSourceNo(1);

        QueryBuildRange qr1 = SysQuery::findOrCreateRange(qbds_dmfDefinitionGroupExecution, fieldNum(DMFDefinitionGroupExecution, ExecutionId));
        qr1.status(RangeStatus::Hidden);
        qr1.value(range);

        this.setQuery(q);
    }
}

/// <summary>
/// Form data source
/// </summary>
/// <param name = "_callerFormDataSource">FormDataSource</param>
/// <returns>FormDataSource</returns>
public FormDataSource  parmFormDataSource(FormDataSource _callerFormDataSource = callerFormDataSource)
{
    callerFormDataSource = _callerFormDataSource;
    return callerFormDataSource;
}

/// <summary>
/// Validate method
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{
    return true;
}
